<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { useResponsiveDrawer } from '../province-monitoring';
import { fail, overdue, permission, sf, sl, statusTone } from '../safety-workspace';
import SafetyMaterials from './SafetyMaterials.vue';
const props=defineProps<{modelValue:boolean;id?:string;taskType?:string}>(),emit=defineEmits<{'update:modelValue':[v:boolean];changed:[]}>(),session=useSessionStore(),router=useRouter(),width=useResponsiveDrawer(650);
const detail=ref<any>(),loading=ref(false),error=ref(''),busy=ref(false),uploading=ref(false),tab=ref('info'),materials=ref<any[]>([]),form=reactive({comment:'',score:undefined as number|undefined,dueAt:''});let generation=0,controller:AbortController|undefined;
const enterprise=computed(()=>session.user?.portal==='ENTERPRISE'),isRect=computed(()=>props.taskType==='RECTIFICATION'),dirty=computed(()=>!!form.comment.trim()||!!form.dueAt||!!form.score||JSON.stringify(materials.value.map(m=>m.id))!==JSON.stringify((detail.value?.materials??[]).map((m:any)=>m.id)));
const actions=computed(()=>{const d=detail.value;if(!d)return [];if(enterprise.value&&permission(session.user,'safety:emergency:respond'))return d.status==='WAITING_RESPONSE'?['RESPOND']:d.status==='IN_PROGRESS'?['SUBMIT_FEEDBACK']:[];if(!enterprise.value){if(d.status==='PENDING_DISPATCH'&&permission(session.user,'safety:emergency:dispatch'))return ['DISPATCH'];if(d.status==='PENDING_REVIEW'&&permission(session.user,'safety:emergency:review'))return ['RETURN','CLOSE'];}return []});
const steps=computed(()=>isRect.value?['WAITING_RESPONSE','IN_PROGRESS','PENDING_REVIEW','CLOSED']:['PENDING_DISPATCH','WAITING_RESPONSE','IN_PROGRESS','PENDING_REVIEW','CLOSED']);
const labelAction=(action:string)=>action==='CLOSE'?'复核通过':sl(action);
async function load(){const g=++generation;controller?.abort();controller=new AbortController();loading.value=true;error.value='';detail.value=undefined;try{const data=await api<any>(`/safety/workspace/tasks/${props.taskType}/${props.id}`,{signal:controller.signal});if(g!==generation)return;detail.value=data;materials.value=[...data.materials];Object.assign(form,{comment:'',score:undefined,dueAt:''})}catch(e){if(g===generation&&!controller.signal.aborted)error.value=fail(e)}finally{if(g===generation)loading.value=false}}
async function confirmDiscard(){if(busy.value||uploading.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('本次填写的办理意见和材料尚未提交，关闭后将放弃这些改动。','放弃未提交内容',{confirmButtonText:'放弃改动',cancelButtonText:'继续填写',type:'warning'});return true}catch{return false}}
async function close(){if(await confirmDiscard())emit('update:modelValue',false)}
async function act(action:string){if(!form.comment.trim())return ElMessage.warning('请填写办理意见');if(action==='CLOSE'&&!isRect.value&&!form.score)return ElMessage.warning('请选择1至5分应急响应评价');if(action==='RETURN'&&overdue(detail.value)&&!form.dueAt)return ElMessage.warning('原期限已过，请填写新的补正期限');busy.value=true;try{const data=await api<any>(`/safety/workspace/tasks/${props.taskType}/${props.id}/actions`,{method:'POST',body:JSON.stringify({action,comment:form.comment.trim(),score:form.score,version:detail.value.version,dueAt:action==='RETURN'&&form.dueAt?new Date(form.dueAt).toISOString():undefined,materialIds:materials.value.map(m=>m.id)})});detail.value=data;materials.value=[...data.materials];Object.assign(form,{comment:'',score:undefined,dueAt:''});ElMessage.success(`${labelAction(action)}成功`);emit('changed')}catch(e){ElMessage.error(fail(e))}finally{busy.value=false}}
async function source(){if(!await confirmDiscard())return;const d=detail.value;if(d.sourceType==='INSPECTION_ISSUE'&&d.inspection){void router.push({path:'/safety/inspections',query:{inspectionId:d.inspection.id}});emit('update:modelValue',false)}else if(['ALERT','ACCIDENT','VIOLATION','OFFLINE'].includes(d.sourceType)){void router.push({path:enterprise.value?'/enterprise/safety/events':'/safety/events',query:{eventKind:d.sourceType,eventId:d.sourceId}});emit('update:modelValue',false)}}
watch(()=>[props.modelValue,props.id,props.taskType],()=>{if(props.modelValue&&props.id&&props.taskType){tab.value='info';void load()}else{generation++;controller?.abort();detail.value=undefined;Object.assign(form,{comment:'',score:undefined,dueAt:''});materials.value=[]}},{immediate:true});
onBeforeUnmount(()=>{generation++;controller?.abort()});defineExpose({confirmDiscard});
</script>
<template><el-drawer :model-value="modelValue" :title="isRect?'整改任务详情':'应急任务详情'" :size="width" class="safety-detail-drawer" :z-index="1700" :modal="false" :close-on-click-modal="false" :before-close="close" destroy-on-close ><div v-if="error" class="safety-error"><strong>任务详情暂时无法读取</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><div v-else v-loading="loading" style="min-height:180px"><template v-if="detail"><div class="safety-identity"><h3>{{detail.title}}</h3><div><span class="safety-muted">{{detail.businessNo}}</span><el-tag size="small" :type="isRect?'warning':'primary'">{{sl(taskType)}}</el-tag><el-tag size="small" :type="statusTone(detail.status)">{{sl(detail.status)}}</el-tag><el-tag v-if="overdue(detail)" size="small" type="danger">已超期</el-tag></div></div><div class="safety-progress" aria-label="任务办理进度"><span v-for="(step,i) in steps" :key="step" :class="{active:step===detail.status,done:i<steps.indexOf(detail.status)}">{{isRect&&step==='IN_PROGRESS'?'整改中':sl(step)}}</span></div><div class="safety-tabs"><button v-for="t in [['info','任务信息'],['logs','办理记录'],['evidence','关联证据']]" :key="t[0]" type="button" :aria-pressed="tab===t[0]" @click="tab=t[0]!">{{t[1]}}</button></div><template v-if="tab==='info'"><dl class="safety-facts"><div class="wide"><dt>关联事项</dt><dd><el-button link type="primary" @click="source">{{detail.sourceTitle}}</el-button></dd></div><div class="wide"><dt>责任企业</dt><dd>{{detail.enterprise?.name}}</dd></div><div><dt>负责人</dt><dd>{{detail.responsibleName}}</dd></div><div><dt>{{isRect?'整改期限':'处置期限'}}</dt><dd :class="{'safety-error-text':overdue(detail)}">{{sf(detail.dueAt)}}</dd></div><div><dt>下达时间</dt><dd>{{sf(detail.dispatchedAt??detail.createdAt)}}</dd></div><div><dt>响应时间</dt><dd>{{sf(detail.respondedAt)}}</dd></div></dl><section class="safety-section"><h4>{{isRect?'整改要求':'处置要求'}}</h4><p>{{detail.requirement}}</p></section><section class="safety-section"><h4>企业反馈</h4><p>{{detail.feedback||'尚未提交反馈'}}</p><SafetyMaterials :model-value="detail.materials"/></section><section v-if="detail.reviewComment" class="safety-section"><h4>监管复核意见</h4><p>{{detail.reviewComment}}</p><span v-if="detail.evaluationScore" class="safety-muted">响应评价 {{detail.evaluationScore}} / 5分</span></section></template><section v-else-if="tab==='logs'" class="safety-section"><ul class="safety-log"><li v-for="(log,i) in detail.history" :key="log.id??i"><strong>{{sl(log.action)}} · {{log.actorName}}</strong><small>{{sf(log.createdAt)}} · {{sl(log.toStatus)}}</small><p>{{log.content}}</p><SafetyMaterials v-if="log.materials?.length" :model-value="log.materials"/></li></ul><el-empty v-if="!detail.history.length" description="暂无办理记录" :image-size="50"/></section><section v-else class="safety-section"><h4>来源证据</h4><p>{{detail.sourceType==='INSPECTION_ISSUE'?'检查问题、现场材料和整改记录可在来源检查中查看。':'关联事件提供事前90秒、事后60秒的视频和轨迹回溯。'}}</p><el-button type="primary" plain @click="source">{{detail.sourceType==='INSPECTION_ISSUE'?'查看来源检查':'查看事件证据'}}</el-button><SafetyMaterials :model-value="detail.materials"/></section><section v-if="actions.length" class="safety-section"><h4>{{enterprise?'办理反馈':'办理意见'}}</h4><el-input v-model="form.comment" type="textarea" :rows="4" maxlength="5000" show-word-limit :aria-label="enterprise?'办理反馈':'办理意见'" :placeholder="enterprise?'填写响应或处置经过、结果与后续措施':'填写复核意见；退回时说明补正要求'"/><template v-if="enterprise&&detail.status==='IN_PROGRESS'"><div style="margin-top:12px"><SafetyMaterials v-model="materials" :enterprise-id="detail.enterpriseId" editable @busy="uploading=$event"/></div></template><div v-if="!enterprise&&detail.status==='PENDING_REVIEW'" class="safety-form-grid" style="margin-top:16px"><el-form-item label="补正期限（退回时）"><el-date-picker v-model="form.dueAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="补正期限"/></el-form-item><el-form-item v-if="!isRect" label="应急响应评价"><el-select v-model="form.score" aria-label="应急响应评价" placeholder="选择1至5分"><el-option v-for="n in [1,2,3,4,5]" :key="n" :label="`${n}分`" :value="n"/></el-select></el-form-item></div></section></template></div><template #footer><el-button :disabled="busy||uploading" @click="close">关闭</el-button><el-button v-for="action in actions" :key="action" :type="action==='RETURN'?'warning':'primary'" :plain="action==='RETURN'" :loading="busy" :disabled="uploading" @click="act(action)">{{labelAction(action)}}</el-button></template></el-drawer></template>
